function fewestRafts(weights: number[], limit: number): number {
  const w = [...weights].sort((a, b) => a - b);
  let lo = 0, hi = w.length - 1, rafts = 0;
  while (lo <= hi) {
    if (w[lo] + w[hi] <= limit) lo++;
    hi--;
    rafts++;
  }
  return rafts;
}

