function fewestRafts(weights: number[], limit: number): number {
  const cnt = new Array(limit + 1).fill(0);
  for (const x of weights) cnt[x]++;
  let left = weights.length, lo = 1, hi = limit, rafts = 0;
  while (left > 0) {
    while (cnt[hi] === 0) hi--;
    cnt[hi]--; left--; rafts++;
    if (left === 0) break;
    while (cnt[lo] === 0) lo++;
    if (lo + hi <= limit) { cnt[lo]--; left--; }
  }
  return rafts;
}

